/** How strongly a due date should draw the eye. */
export type DueTone = "alert" | "emphasis" | "quiet";

/** The text and tone a task row shows for its due date. */
export interface DueLabel {
  readonly text: string;
  readonly tone: DueTone;
}

const dayMs = 86_400_000;

const toUtc = (isoDate: string): Date => new Date(`${isoDate}T00:00:00Z`);

const daysBetween = (from: string, to: string): number =>
  Math.round((toUtc(to).getTime() - toUtc(from).getTime()) / dayMs);

const sameYear = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  month: "short",
  day: "numeric",
  timeZone: "UTC",
});

const otherYear = new Intl.DateTimeFormat("en-US", {
  weekday: "short",
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

const formatDate = (dueDate: string, today: string): string =>
  (dueDate.slice(0, 4) === today.slice(0, 4) ? sameYear : otherYear).format(toUtc(dueDate));

/** Describe a `YYYY-MM-DD` due date relative to today; a completed task is never overdue. */
export const dueLabel = (dueDate: string, today: string, completed: boolean): DueLabel => {
  const days = daysBetween(today, dueDate);
  const date = formatDate(dueDate, today);
  if (completed) return { text: `Due ${date}`, tone: "quiet" };
  if (days < 0) return { text: `Overdue · ${date}`, tone: "alert" };
  if (days === 0) return { text: "Due today", tone: "emphasis" };
  if (days === 1) return { text: "Due tomorrow", tone: "quiet" };
  return { text: `Due ${date}`, tone: "quiet" };
};

import type { Task } from "./schema/task.ts";

/** Open and completed counts for a list of tasks. */
export interface TaskSummary {
  readonly open: number;
  readonly done: number;
}

/** A reorder as the API takes it: put `taskId` right after `afterId`, or at the top when null. */
export interface Move {
  readonly taskId: string;
  readonly afterId: string | null;
}

/** Count open and completed tasks. */
export const summarize = (tasks: readonly Task[]): TaskSummary =>
  tasks.reduce<TaskSummary>(
    (counts, task) =>
      task.completed ? { ...counts, done: counts.done + 1 } : { ...counts, open: counts.open + 1 },
    { open: 0, done: 0 },
  );

/** Turn a drop of `activeId` onto `overId`'s place into the move the API expects, or null for no change. */
export const moveFor = (ids: readonly string[], activeId: string, overId: string): Move | null => {
  const from = ids.indexOf(activeId);
  const to = ids.indexOf(overId);
  if (from === -1 || to === -1 || from === to) return null;
  const reordered = ids.toSpliced(from, 1).toSpliced(to, 0, activeId);
  return { taskId: activeId, afterId: reordered[to - 1] ?? null };
};

/** The detail route for one task. */
export const taskPath = (taskId: string): string => `/tasks/${taskId}`;

import { type Task, taskSchema } from "../lib/schema/task.ts";

/** The date every fixture is relative to: Monday 19 October 2026. */
export const today = "2026-10-19";

let sequence = 0;

/** Build one valid task, parsed through the real schema, with any fields overridden. */
export const makeTask = (overrides: Partial<Task> = {}): Task => {
  sequence += 1;
  const suffix = sequence.toString(16).padStart(12, "0");
  return taskSchema.parse({
    id: `00000000-0000-4000-8000-${suffix}`,
    title: "Water the plants",
    notes: "",
    completed: false,
    dueDate: null,
    rank: `a${sequence.toString(36)}`,
    version: 1,
    createdAt: "2026-10-12T08:30:00Z",
    updatedAt: "2026-10-12T08:30:00Z",
    ...overrides,
  });
};

/** A realistic week of tasks: overdue, due today, upcoming, undated, completed, and one long title. */
export const tasks: readonly Task[] = [
  makeTask({
    title: "Call the landlord about the boiler service",
    notes: "The annual service is due before the cold weather. Ask about the back bedroom radiator.",
    dueDate: "2026-10-19",
  }),
  makeTask({
    title: "Send Maya the Q3 budget notes",
    notes: "She needs the travel line split out by team.",
    dueDate: "2026-10-16",
  }),
  makeTask({
    title: "Renew passport before the Lisbon trip",
    notes: "Photos are in the desk drawer. Check the fee first.",
    dueDate: "2026-10-24",
  }),
  makeTask({
    title: "Draft the agenda for the budget review",
    dueDate: "2026-10-21",
  }),
  makeTask({
    title:
      "Get three quotes for repointing the brickwork on the back wall, and ask each one about scaffolding",
    dueDate: "2026-11-06",
  }),
  makeTask({ title: "Book a dentist check-up" }),
  makeTask({ title: "Return the library books", completed: true, dueDate: "2026-10-17" }),
  makeTask({ title: "Pick up the dry cleaning", completed: true }),
];

/** A search term that matches two tasks, and those matches in rank order. */
export const searchTerm = "budget";

/** The tasks that match `searchTerm`. */
export const searchMatches: readonly Task[] = tasks.filter((task) =>
  task.title.toLowerCase().includes(searchTerm),
);

/** A search term that matches nothing. */
export const unmatchedTerm = "plumber";

