      <path d="m15.75 15.75 4 4" />
    </>
  ),
  grip: (
    <g fill="currentColor" stroke="none">
      {[6, 12, 18].flatMap((y) =>
        [9, 15].map((x) => <circle key={`${String(x)}-${String(y)}`} cx={x} cy={y} r="1.5" />),
      )}
    </g>
  ),
  check: <path d="m5.5 12.5 4.25 4.25L18.5 7.5" strokeWidth="2.25" />,
  plus: <path d="M12 5.5v13M5.5 12h13" />,
  close: <path d="m7 7 10 10M17 7 7 17" />,
  alert: (
    <>
      <circle cx="12" cy="12" r="8.25" />
      <path d="M12 7.75v5" />
      <circle cx="12" cy="16" r="0.5" fill="currentColor" />
    </>
  ),
} satisfies Record<string, ReactNode>;

/** The names of the glyphs `Icon` can draw. */
export type IconName = keyof typeof glyphs;

/** Props for `Icon`. */
export interface IconProps {
  readonly name: IconName;
  readonly className?: string;
}

/** A decorative line glyph drawn in the current text colour; the control around it carries the name. */
export function Icon({ name, className = "size-5" }: IconProps) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      className={className}
    >
      {glyphs[name]}
    </svg>
  );
}

import type { ComponentProps } from "react";

const variants = {
  primary: "bg-primary text-on-primary hover:bg-primary-strong",
  secondary: "border border-rule-strong bg-sheet text-ink hover:border-ink",
  ghost: "text-ink-muted hover:bg-rule/40 hover:text-ink",
} as const;

/** The visual weight of a button. */
export type ButtonVariant = keyof typeof variants;

/** Props for `Button`: a native button plus its variant. */
export interface ButtonProps extends ComponentProps<"button"> {
  readonly variant?: ButtonVariant;
}

/** A real button, at least 44px tall, in one of three weights. */
export function Button({
  variant = "secondary",
  type = "button",
  className = "",
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      className={`inline-flex min-h-touch min-w-touch shrink-0 cursor-pointer items-center justify-center gap-2 rounded-control px-4 font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-60 ${variants[variant]} ${className}`}
      {...props}
    />
  );
}

import { type ComponentProps, type MouseEvent, type ReactNode, createContext, use } from "react";

type Navigate = (href: string) => void;

const NavigationContext = createContext<Navigate | null>(null);

/** Props for `NavigationProvider`. */
export interface NavigationProviderProps {
  readonly navigate: Navigate;
  readonly children: ReactNode;
}

/** Lets every `Link` below it navigate inside the app instead of reloading the page. */
export function NavigationProvider({ navigate, children }: NavigationProviderProps) {
  return <NavigationContext value={navigate}>{children}</NavigationContext>;
}

/** True for a click the app should handle itself: the main button, with no modifier key. */
export const isPlainClick = (event: MouseEvent): boolean =>
  event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey;

/** Props for `Link`: a native anchor that always has an `href`. */
export interface LinkProps extends ComponentProps<"a"> {
  readonly href: string;
}

/** A real link: a plain click navigates in the app, any other click is left to the browser. */
export function Link({ href, onClick, ...props }: LinkProps) {
  const navigate = use(NavigationContext);
  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (!navigate || event.defaultPrevented || !isPlainClick(event)) return;
    event.preventDefault();
    navigate(href);
  };
  return <a href={href} onClick={handleClick} {...props} />;
}

import { type ComponentProps, useId } from "react";

/** The input style every text field shares, exported so `SearchBox` uses the same one. */
export const fieldClass =
  "min-h-touch w-full rounded-control border border-rule-strong bg-sheet px-3 text-ink transition-colors placeholder:text-ink-muted hover:border-ink aria-invalid:border-alert disabled:opacity-60";

/** Props for `TextField`: a native input plus its label and an optional error. */
export interface TextFieldProps extends Omit<ComponentProps<"input">, "id"> {
  readonly label: string;
  readonly hideLabel?: boolean;
  readonly error?: string | undefined;
}

/** A labelled text input that shows its error underneath and links the two for screen readers. */
export function TextField({
  label,
  hideLabel = false,
  error,
  className = "",
  ...props
}: TextFieldProps) {
  const id = useId();
  const errorId = `${id}-error`;
  return (
    <div className={`flex flex-col gap-1 ${className}`}>
      <label htmlFor={id} className={hideLabel ? "sr-only" : "text-caption font-medium text-ink"}>
        {label}
      </label>
      <input
        id={id}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
        className={fieldClass}
        {...props}
      />
      {error && (
        <p id={errorId} className="text-caption text-alert">
          {error}
        </p>
      )}
    </div>
  );
}

import { Icon } from "./icon.tsx";

/** Props for `Checkbox`. */
export interface CheckboxProps {
  readonly label: string;
  readonly checked: boolean;
  readonly onChange: (checked: boolean) => void;
}

/** A native checkbox drawn as a ledger tick box, with a 44px hit area around a 20px box. */
export function Checkbox({ label, checked, onChange }: CheckboxProps) {
  return (
    <span className="relative inline-flex size-touch shrink-0 items-center justify-center">
      <input
        type="checkbox"
        aria-label={label}
        checked={checked}
        onChange={(event) => {
          onChange(event.target.checked);
        }}
        className="peer absolute inset-0 m-0 cursor-pointer appearance-none outline-none"
      />
      <span
        aria-hidden="true"
        className="pointer-events-none flex size-5 items-center justify-center rounded-control border border-rule-strong bg-sheet text-on-primary transition-colors peer-hover:border-ink peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-focus peer-checked:border-primary peer-checked:bg-primary [&>svg]:opacity-0 peer-checked:[&>svg]:opacity-100"
      >
        <Icon name="check" className="size-4" />
      </span>
    </span>
  );
}

import { useId, useRef } from "react";
import { Icon } from "./icon.tsx";
import { fieldClass } from "./text-field.tsx";

/** Props for `SearchBox`. */
export interface SearchBoxProps {
  readonly label: string;
  readonly value: string;
  readonly onChange: (value: string) => void;
  readonly placeholder?: string;
  readonly busy?: boolean;
  readonly className?: string;
}

/** A labelled search input with a clear button; `busy` dims the glass while results load. */
export function SearchBox({
  label,
  value,
  onChange,
  placeholder,
  busy = false,
  className = "",
}: SearchBoxProps) {
  const id = useId();
  const input = useRef<HTMLInputElement>(null);
  return (
    <div className={`relative ${className}`}>
      <label htmlFor={id} className="sr-only">
        {label}
      </label>
      <Icon
        name="search"
        className={`pointer-events-none absolute top-3 left-3 size-5 text-ink-muted ${busy ? "motion-safe:animate-shimmer" : ""}`}
      />
      <input
        ref={input}
        id={id}
        type="search"
        value={value}
        placeholder={placeholder}
        onChange={(event) => {
          onChange(event.target.value);
        }}
        className={`${fieldClass} px-12 [&::-webkit-search-cancel-button]:appearance-none`}
      />
      {value !== "" && (
        <button
          type="button"
          aria-label="Clear search"
          onClick={() => {
            onChange("");
            input.current?.focus();
          }}
          className="absolute top-0 right-0 flex size-touch cursor-pointer items-center justify-center text-ink-muted transition-colors hover:text-ink"
        >
          <Icon name="close" />
        </button>
      )}
    </div>
  );
}

import type { ReactNode } from "react";
import { Button } from "./button.tsx";
import { Icon } from "./icon.tsx";

/** A button a notice offers, such as "Try again". */
export interface NoticeAction {
  readonly label: string;
  readonly onAction: () => void;
}

/** Props for `Notice`. */
export interface NoticeProps {
  readonly tone: "alert" | "info";
  readonly children: ReactNode;
  readonly action?: NoticeAction | undefined;
  readonly onDismiss?: (() => void) | undefined;
}

const tones = {
  alert: { role: "alert", className: "border-alert/50 bg-alert/8", icon: "text-alert" },
  info: { role: "status", className: "border-rule bg-sheet", icon: "text-ink-muted" },
} as const;

/** An inline message about something that happened, announced to screen readers, with an optional action. */
export function Notice({ tone, children, action, onDismiss }: NoticeProps) {
  const style = tones[tone];
  return (
    <div
      role={style.role}
      className={`flex items-center gap-3 rounded-control border py-1 pr-1 pl-4 ${style.className}`}
    >
      <Icon name="alert" className={`size-5 shrink-0 ${style.icon}`} />
      <p className="min-w-0 flex-1 py-2 text-ink">{children}</p>
      {action && <Button onClick={action.onAction}>{action.label}</Button>}
      {onDismiss && (
        <Button variant="ghost" aria-label="Dismiss" onClick={onDismiss} className="px-0">
          <Icon name="close" />
        </Button>
      )}
    </div>
  );
}

import type { ReactNode } from "react";

/** Props for `EmptyState`. */
export interface EmptyStateProps {
  readonly title: string;
  readonly children: ReactNode;
  readonly action?: ReactNode;
  readonly tone?: "quiet" | "alert";
}

/** A centred message for a list with nothing to show, or one that could not load. */
export function EmptyState({ title, children, action, tone = "quiet" }: EmptyStateProps) {
  return (
    <div
      role={tone === "alert" ? "alert" : undefined}
      className="flex flex-col items-center gap-2 px-6 py-12 text-center"
    >
      <h2
        className={`font-display text-title text-balance ${tone === "alert" ? "text-alert" : "text-ink"}`}
      >
        {title}
      </h2>
      <p className="max-w-measure text-ink-muted">{children}</p>
      {action && <div className="pt-4">{action}</div>}
    </div>
  );
}

/** Props for `Skeleton`. */
export interface SkeletonProps {
  readonly className?: string;
}

/** A placeholder bar that breathes while content loads; it stays still under reduced motion. */
export function Skeleton({ className = "" }: SkeletonProps) {
  return (
    <span
      aria-hidden="true"
      className={`block rounded-control bg-rule/70 motion-safe:animate-shimmer ${className}`}
    />
  );
}

