  it("builds the detail route for a task", () => {
    expect(taskPath("3f0c6f7e-8a51-4f7a-9d64-2f0b9c1e5a10")).toBe(
      "/tasks/3f0c6f7e-8a51-4f7a-9d64-2f0b9c1e5a10",
