@import "tailwindcss";
@import "@fontsource-variable/besley/wght.css";
@import "@fontsource-variable/libre-franklin/wght.css";
@import "./tokens.css";

@source "..";
@source "../../design";

/* Hover, focus and press also match a data attribute, so the design gallery can show each state on the real components. The app never sets these attributes. */
@custom-variant hover {
  &:where([data-hover]) {
    @slot;
  }
  @media (hover: hover) {
    &:hover {
      @slot;
    }
  }
}
@custom-variant focus-visible (&:where(:focus-visible, [data-focus-visible]));
@custom-variant active (&:where(:active, [data-active]));

/* The binding: a band of cloth with gilt tooling, where the focus ring turns gilt to stay visible. */
@utility binding {
  background-color: var(--color-binding);
  color: var(--color-on-binding);
  --color-focus: var(--color-gilt);
}

@layer base {
  body {
    background-color: var(--color-canvas);
    color: var(--color-ink);
    font-family: var(--font-body);
    font-size: var(--text-body);
    line-height: var(--text-body--line-height);
    -webkit-font-smoothing: antialiased;
  }

  :focus-visible,
  [data-focus-visible] {
    outline: 2px solid var(--color-focus);
    outline-offset: 2px;
  }

  ::selection {
    background-color: var(--color-primary);
    color: var(--color-on-primary);
  }
}

