  readonly children: ReactNode;
  readonly footer: ReactNode;
}

/**
 * The ledger opened at its title page: the cloth cover with the title tooled in gilt inside a blind-stamped double
 * frame, and beside it (below it on a phone) the first page, which holds the form.
 */
export function AuthLayout({ title, children, footer }: AuthLayoutProps) {
  const headingId = useId();
  return (
    <div className="@container min-h-dvh bg-binding text-on-binding">
      <div className="mx-auto grid max-w-book gap-6 px-4 py-8 @wide:grid-cols-2 @wide:items-stretch @wide:gap-12 @wide:px-8 @wide:py-16">
        <div className="flex flex-col items-center justify-center gap-6 border-3 border-double border-gilt/60 px-6 py-10 text-center @wide:py-24">
          <LedgerTitle size="cover" />
          <span aria-hidden="true" className="h-px w-12 bg-gilt/60" />
          <p className="text-caption font-medium tracking-caps uppercase">
            A ledger for the things you mean to do
          </p>
        </div>
        <article
          aria-labelledby={headingId}
          className="flex flex-col gap-6 rounded-sheet bg-sheet px-6 py-8 text-ink shadow-sheet @wide:justify-center @wide:px-12 @wide:py-12"
        >
          <h1 id={headingId} className="font-display text-title font-medium">
            {title}
          </h1>
          {children}
          <p className="text-ink-muted">{footer}</p>
        </article>
      </div>
    </div>
  );
}

import { AuthLayout } from "../components/auth-layout.tsx";
import { CredentialsForm, unreachableMessage } from "../components/credentials-form.tsx";
import { Link, textLinkClass } from "../components/ui/link.tsx";
import { routes } from "../lib/routes.ts";
import type { Credentials } from "../lib/schema/auth.ts";

/** Why the last sign-in failed: a 401, or no answer from the server. */
export type SignInFailure = "wrong-credentials" | "unreachable";

/** Props for `SignInView`. */
export interface SignInViewProps {
  readonly submitting: boolean;
  readonly failure: SignInFailure | null;
  readonly initialEmail?: string | undefined;
  readonly onSubmit: (credentials: Credentials) => void;
}

const messages: Readonly<Record<SignInFailure, string>> = {
  "wrong-credentials": "That email and password don't match an account. Check both and try again.",
  unreachable: unreachableMessage,
};

/** The landing page: sign in, or go and create an account. */
export function SignInView({ submitting, failure, initialEmail, onSubmit }: SignInViewProps) {
  return (
    <AuthLayout
      title="Sign in"
      footer={
        <>
          New here?{" "}
          <Link href={routes.signUp} className={textLinkClass}>
            Create an account
          </Link>
        </>
      }
    >
      <CredentialsForm
        submitLabel="Sign in"
        submittingLabel="Signing in…"
        passwordAutoComplete="current-password"
        submitting={submitting}
        failure={failure && messages[failure]}
        initialEmail={initialEmail}
        onSubmit={onSubmit}
      />
    </AuthLayout>
  );
}

import type { ReactNode } from "react";
import { AuthLayout } from "../components/auth-layout.tsx";
import { CredentialsForm, unreachableMessage } from "../components/credentials-form.tsx";
import { Link, textLinkClass } from "../components/ui/link.tsx";
import { routes } from "../lib/routes.ts";
import type { Credentials } from "../lib/schema/auth.ts";

/** Why the last sign-up failed: a 409 for a registered email, or no answer from the server. */
export type SignUpFailure = "email-taken" | "unreachable";

/** Props for `SignUpView`. */
export interface SignUpViewProps {
  readonly submitting: boolean;
  readonly failure: SignUpFailure | null;
  readonly onSubmit: (credentials: Credentials) => void;
}

const messages: Readonly<Record<SignUpFailure, ReactNode>> = {
  "email-taken": (
    <>
      An account with this email already exists.{" "}
      <Link href={routes.signIn} className={textLinkClass}>
        Sign in instead
      </Link>
    </>
  ),
  unreachable: unreachableMessage,
};

/** Create an account with an email and a password of 12 to 128 characters. */
export function SignUpView({ submitting, failure, onSubmit }: SignUpViewProps) {
  return (
    <AuthLayout
      title="Create an account"
      footer={
        <>
          Already have an account?{" "}
          <Link href={routes.signIn} className={textLinkClass}>
            Sign in
          </Link>
        </>
      }
    >
      <CredentialsForm
        submitLabel="Create account"
        submittingLabel="Creating account…"
        passwordAutoComplete="new-password"
        passwordHint="At least 12 characters."
        submitting={submitting}
        failure={failure && messages[failure]}
        onSubmit={onSubmit}
      />
    </AuthLayout>
  );
}

