import glob
import re
import sys

root = sys.argv[1]
css = open(f"{root}/design/dist/artifact.html").read()
sources = glob.glob(f"{root}/src/**/*.tsx", recursive=True) + glob.glob(f"{root}/design/**/*.tsx", recursive=True) + glob.glob(f"{root}/design/**/*.ts", recursive=True)
strings = []
for path in sources:
    if ".test." in path:
        continue
    text = open(path).read()
    strings += [(path, m) for m in re.findall(r'"([^"]*)"', text)]
    strings += [(path, m) for m in re.findall(r"`([^`]*)`", text)]


def escape(cls: str) -> str:
    return re.sub(r"([^a-zA-Z0-9_-])", r"\\\1", cls)


missing = set()
for path, s in strings:
    for cls in s.split():
        if "${" in cls or "}" in cls or not re.match(r"^[@a-z\[\-!][\w\-:/@\[\]().&>*_,=%#'~+.]*$", cls):
            continue
        if escape(cls) not in css:
            missing.add((path.split("/frontend/")[-1], cls))
for path, cls in sorted(missing):
    print(path, cls)

