import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";

const require = createRequire(process.argv[2] + "/package.json");
const { chromium } = require("playwright");
const artifact = await readFile(process.argv[2] + "/design/dist/artifact.html", "utf8");
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head><body>${artifact}</body></html>`;
const browser = await chromium.launch();
for (const theme of ["light", "dark"]) {
  const page = await browser.newPage({ viewport: { width: 320, height: 800 }, colorScheme: theme });
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
  await page.setContent(html, { waitUntil: "load" });
  await page.waitForTimeout(500);
  const report = await page.evaluate(() => {
    const doc = document.documentElement;
    const pageOverflow = doc.scrollWidth - doc.clientWidth;
    // Phone frames are the first figure in each state; anything wider than its frame is clipped content.
    const clipped = [...document.querySelectorAll("article[data-state] figure:first-of-type")]
      .flatMap((figure) => {
        const box = figure.getBoundingClientRect();
        return [...figure.querySelectorAll("*")]
          .filter((el) => el.getBoundingClientRect().right > box.right + 1 && el.getClientRects().length > 0)
          .slice(0, 1)
          .map((el) => `${figure.closest("article").dataset.state}: <${el.tagName.toLowerCase()} class="${String(el.className).slice(0, 60)}">`);
      });
    return { pageOverflow, phoneWidth: document.querySelector("figure")?.getBoundingClientRect().width, clipped };
  });
  console.log(theme, JSON.stringify(report, null, 1), "errors:", errors.length ? errors : "none");
  await page.close();
}
await browser.close();

