import { readFile } from "node:fs/promises";
import { createRequire } from "node:module";

const require = createRequire(process.argv[2] + "/package.json");
const { chromium } = require("playwright");
const artifact = await readFile(process.argv[2] + "/design/dist/artifact.html", "utf8");
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head><body>${artifact}</body></html>`;
const browser = await chromium.launch();
for (const width of [320, 390]) {
  for (const theme of ["light", "dark"]) {
    const page = await browser.newPage({ viewport: { width, height: 900 }, colorScheme: theme });
    await page.setContent(html, { waitUntil: "load" });
    await page.evaluate((value) => {
      document.documentElement.dataset.theme = value;
    }, theme);
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(400);
    const lines = await page.evaluate(() => {
      // The phone frame of the first sign-in state: split the cover subtitle into its rendered lines.
      const subtitle = [...document.querySelectorAll('[data-state="sign-in-idle"] figure:first-of-type p')].find((p) =>
        p.textContent.startsWith("A ledger"),
      );
      const words = subtitle.textContent.split(" ");
      const text = subtitle.firstChild;
      const rows = new Map();
      let offset = 0;
      for (const word of words) {
        const range = document.createRange();
        range.setStart(text, offset);
        range.setEnd(text, offset + word.length);
        const top = Math.round(range.getBoundingClientRect().top);
        rows.set(top, [...(rows.get(top) ?? []), word]);
        offset += word.length + 1;
      }
      return [...rows.values()].map((row) => row.join(" "));
    });
    console.log(`${String(width)} ${theme}:`, JSON.stringify(lines), "overflow:", await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));
    await page.close();
  }
}
await browser.close();

