import { readdir } from "node:fs/promises";
import { createRequire } from "node:module";
import { join } from "node:path";

const require = createRequire(process.argv[2] + "/package.json");
const sharp = require("sharp");
const committed = join(process.argv[2], "design/screenshots");
const fresh = process.argv[3];

const raw = (path) => sharp(path).ensureAlpha().raw().toBuffer({ resolveWithObject: true });

const files = [
  ...(await readdir(committed)).filter((f) => f.endsWith(".png")),
  ...(await readdir(join(committed, "states"))).map((f) => `states/${f}`),
];
const results = [];
for (const file of files) {
  const [a, b] = await Promise.all([raw(join(committed, file)), raw(join(fresh, file))]);
  if (a.info.width !== b.info.width || a.info.height !== b.info.height) {
    results.push({ file, note: `size ${a.info.width}x${a.info.height} -> ${b.info.width}x${b.info.height}` });
    continue;
  }
  let differing = 0;
  for (let i = 0; i < a.data.length; i += 4) {
    const delta = Math.max(...[0, 1, 2].map((c) => Math.abs(a.data[i + c] - b.data[i + c])));
    if (delta > 24) differing += 1;
  }
  results.push({ file, share: differing / (a.info.width * a.info.height) });
}
const sized = results.filter((r) => r.note);
const worst = results.filter((r) => !r.note).sort((x, y) => y.share - x.share).slice(0, 5);
console.log("files compared:", results.length, "size changes:", sized.length);
console.log(sized.slice(0, 10));
console.log("largest pixel differences:", worst.map((r) => `${r.file} ${(r.share * 100).toFixed(3)}%`));

